(25720,1,'2026-05-29 14:27:57','2026-05-29 12:27:57','<!-- wp:group {\"className\":\"iss-project-dossier\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-project-dossier\"><!-- wp:paragraph {\"className\":\"iss-project-dossier__lead\"} -->\n<p class=\"iss-project-dossier__lead\">Der Walk of Fame Schöneweide macht Industriekultur entlang der Wilhelminenhofstraße sichtbar. Bewegliche Sehrohre lenken den Blick auf Gebäude, Blickachsen und Geschichten, die im Alltag oft übersehen werden.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:iss/dense-image-wall {\"editMode\":\"annotate\",\"items\":[{\"id\":26425,\"url\":\"/wp-content/uploads/2026/05/image5.webp\",\"alt\":\"\",\"kicker\":\"Beispiel\",\"title\":\"\",\"text\":\"Blick auf die historische Montagehalle im \\nTransformatorenwerk Oberschöneweide\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":2,\"rowSpan\":5},{\"id\":26426,\"url\":\"/wp-content/uploads/2026/05/image4.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"\",\"text\":\" 1927 wurde er in dieser Halle gebaut:        Der größte Einphasen-Transformator            der Welt \",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":3},{\"id\":25803,\"url\":\"/wp-content/uploads/2026/05/walk-of-fame-spyglass.png\",\"alt\":\"Rotes Sehrohr mit historischem Blickmotiv für Walk of Fame Schöneweide\",\"kicker\":\"\",\"title\":\"Walk of Fame Schöneweide Sehrohr\",\"text\":\"\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"\",\"colSpan\":1,\"rowSpan\":5},{\"id\":26424,\"url\":\"/wp-content/uploads/2026/05/image6.webp\",\"alt\":\"\",\"kicker\":\"Der Künstler\",\"title\":\"Rainer Düvell \",\"text\":\"Als Künstler und Architekt hat er zahlreiche\\nAusstellungen und Installationen realisiert\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"https://www.transform-info.de/rainer-duvell/\",\"colSpan\":1,\"rowSpan\":2},{\"id\":26427,\"url\":\"/wp-content/uploads/2026/05/image3.webp\",\"alt\":\"\",\"kicker\":\"\",\"title\":\"Walk of Fame Schöneweide\",\"text\":\"ist gedeckt von der Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, \\nIndustrie und Betriebe und einen Zuschuss aus bezirksübergreifenden CItyTax-Mitteln.\",\"caption\":\"\",\"captionHtml\":\"\",\"className\":\"\",\"captionClassName\":\"\",\"linkUrl\":\"https://industriekultur.berlin/erleben/festival/\",\"colSpan\":4,\"rowSpan\":1}]} -->\n<div class=\"wp-block-group iss-dense-image-wall\"><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 2;grid-row:span 5\"><img src=\"/wp-content/uploads/2026/05/image5.webp\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__kicker\">Beispiel</p><p class=\"iss-dense-image-wall__text\">Blick auf die historische Montagehalle im \nTransformatorenwerk Oberschöneweide</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 3\"><img src=\"/wp-content/uploads/2026/05/image4.webp\" alt=\"\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__text\"> 1927 wurde er in dieser Halle gebaut:        Der größte Einphasen-Transformator            der Welt </p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 5\"><img src=\"/wp-content/uploads/2026/05/walk-of-fame-spyglass.png\" alt=\"Rotes Sehrohr mit historischem Blickmotiv für Walk of Fame Schöneweide\"/><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Walk of Fame Schöneweide Sehrohr</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--tall iss-dense-image-wall__cell--captioned\" style=\"grid-row:span 2\"><a href=\"https://www.transform-info.de/rainer-duvell/\"><img src=\"/wp-content/uploads/2026/05/image6.webp\" alt=\"\"/></a><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__kicker\">Der Künstler</p><p class=\"iss-dense-image-wall__title\">Rainer Düvell </p><p class=\"iss-dense-image-wall__text\">Als Künstler und Architekt hat er zahlreiche\nAusstellungen und Installationen realisiert</p></figcaption></figure><figure class=\"wp-block-image iss-dense-image-wall__cell iss-dense-image-wall__cell--wide iss-dense-image-wall__cell--captioned\" style=\"grid-column:span 4\"><a href=\"https://industriekultur.berlin/erleben/festival/\"><img src=\"/wp-content/uploads/2026/05/image3.webp\" alt=\"\"/></a><figcaption class=\"iss-dense-image-wall__caption\"><p class=\"iss-dense-image-wall__title\">Walk of Fame Schöneweide</p><p class=\"iss-dense-image-wall__text\">ist gedeckt von der Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, \nIndustrie und Betriebe und einen Zuschuss aus bezirksübergreifenden CItyTax-Mitteln.</p></figcaption></figure></div>\n<!-- /wp:iss/dense-image-wall -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"worum-es-geht\"} -->\n<section id=\"worum-es-geht\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Worum es geht</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Industriekultur wird zum Blickpunkt im Straßenraum.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Walk of Fame Schöneweide ist als Auftakt und Teil des Festivals der Berliner Industriekultur geplant. Während des Festivalzeitraums vom 12. September bis 4. Oktober 2026 sollen Sehrohre entlang der Wilhelminenhofstraße den Blick auf prägende Orte der Industriekultur lenken.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Initiator und Organisator ist der Industriesalon Schöneweide e.V. Das Projekt stärkt den Standort, indem es vorhandene Gebäude, Unternehmen und Einrichtungen nicht nur beschreibt, sondern als sichtbare Stationen im öffentlichen Raum erfahrbar macht.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"className\":\"iss-project-chapter__cards\"} -->\n<div class=\"wp-block-columns iss-project-chapter__cards\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">12.09.-04.10.2026</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Geplanter Festivalzeitraum im Rahmen der Berliner Industriekultur.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">29 Standorte</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Das Tiefbauamt Treptow-Köpenick hat Standorte für Sehrohre entlang der Wilhelminenhofstraße genehmigt.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"iss-context-panel\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group iss-context-panel\"><!-- wp:paragraph {\"className\":\"iss-context-panel__label\"} -->\n<p class=\"iss-context-panel__label\">Eröffnung</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Geplant für den 12. September 2026 um 14 Uhr.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"konzept\"} -->\n<section id=\"konzept\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Konzept</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Sehrohre als einfache, robuste Vermittlungsform.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Sehrohre werden von Rainer Düvell gebaut. Als Künstler und Architekt arbeitet er mit Installationen, die Raumsituationen über aktive Wahrnehmung erfahrbar machen. Für Schöneweide wird dieses Prinzip in den Stadtraum übertragen: Wer in ein Sehrohr schaut, folgt einer gesetzten Blickachse.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-rail\"} -->\n<ul class=\"wp-block-list is-style-iss-list-rail\"><!-- wp:list-item -->\n<li><strong>Material:</strong> oxidiertes Metall, robust genug für den öffentlichen Raum.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Beweglichkeit:</strong> Die Sehrohre können auf unterschiedliche Körpergrößen reagieren.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vermittlung:</strong> Die Installation ersetzt keine Geschichte, sondern öffnet den ersten Blick darauf.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"mitwirken\"} -->\n<section id=\"mitwirken\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Mitwirken</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Patenschaften halten den Walk of Fame im Quartier.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Zum „Fame“ von Schöneweide gehören auch die Unternehmen, Headquarter und Einrichtungen, die heute am Standort arbeiten. Sie sollen als Nachbarn sichtbar werden und zugleich helfen, die Sehrohre vor Diebstahl und Zerstörung zu schützen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li>Gewerbetreibende und Anwohner entlang der Wilhelminenhofstraße können als Paten angesprochen werden.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Interessenten können ein individuelles Sehrohr gestalten und bauen lassen.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Partner werden für die Festivaldauer im Industriesalon Schöneweide sichtbar gemacht.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"material\"} -->\n<section id=\"material\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Material</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Flyer, Festivalbezug und Künstlerkontext.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Der Flyer verknüpft das lokale Projekt mit dem Festival der Berliner Industriekultur und stellt die Sehrohre als künstlerische Intervention im Stadtraum vor.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"is-style-iss-list-facts\"} -->\n<ul class=\"wp-block-list is-style-iss-list-facts\"><!-- wp:list-item -->\n<li><strong>Festival:</strong> <a href=\"https://industriekultur.berlin/erleben/festival/\">Festival der Berliner Industriekultur</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Künstler:</strong> <a href=\"https://www.transform-info.de/rainer-duvell/\">Rainer Düvell</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Quelle:</strong> vierseitiger Flyer „Walk of Fame Schöneweide“, Stand 27. Mai 2026.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"rueckblick\"} -->\n<section id=\"rueckblick\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Rückblick</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Stand Mai 2026.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Die Basisfinanzierung ist laut Flyer über die Projektförderung des Vereins durch die Senatsverwaltung für Wirtschaft, Energie und Betriebe sowie über bezirksübergreifende City-Tax-Mittel gedeckt. Die Standorte entlang der Wilhelminenhofstraße sind genehmigt; die nächste Aufgabe ist die Abstimmung mit Partnern und Paten im Quartier.</p>\n<!-- /wp:paragraph --></section>\n<!-- /wp:group -->\n\n<!-- wp:group {\"tagName\":\"section\",\"className\":\"iss-project-chapter\",\"layout\":{\"type\":\"default\"},\"anchor\":\"kontakt\"} -->\n<section id=\"kontakt\" class=\"wp-block-group iss-project-chapter\"><!-- wp:paragraph {\"className\":\"iss-project-chapter__kicker\"} -->\n<p class=\"iss-project-chapter__kicker\">Kontakt</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Abstimmung über den Industriesalon.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Für Patenschaften, Beteiligung und weitere Abstimmung bleibt die Kontaktinformation zentral gepflegt. Personenbezogene Telefon- und E-Mail-Angaben aus dem Flyer werden nicht als freie Projektprosa dupliziert.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:industriesalon/field {\"key\":\"contact.email\",\"tagName\":\"p\",\"linkMode\":\"email\",\"label\":\"E-Mail:\",\"hrefSuffix\":\"?subject=Walk%20of%20Fame%20Sch%C3%B6neweide\"} /--></section>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Walk of Fame Schöneweide','INSTALLATION MIT SEHROHREN AUF DER WILHELMINENHOFSTRAßE\n\nBürgermeister Igel und Musik, Spiel & Spaß.\nIm Rahmen des Festivals der Berliner Industriekultur 2026.','publish','closed','closed','','walk-of-fame-schoeneweide','','','2026-06-14 12:37:36','2026-06-14 10:37:36','',0,'/projekte/walk-of-fame-schoeneweide/',10,'projekt','',0),
